-- Rifts World Book 9: South America 2 - its named NPCs and its creatures:
-- rows for notable_npcs and creatures, and their attacks in stat_attacks
-- (owner_kind 'notable_npc' and 'creature').
--
--   notable_npcs (6): the Pantheon of the Sun - Viracocha, Inti, Pachamama,
--     Illapa (printed 41-46) - Manco Capac, the First Inca, a 14th-level True
--     Inca godling (46-47); and Yahuar Huacac, the Blood Weeper, an Ancient
--     necromancer (50-52).
--   creatures (2): the Ancient, the Incan undead R.C.C. the book says is not
--     for player characters (48-50), and the War Bison, the Larhold's
--     supernatural mount (187-188).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-south-america-2-npcs-and-creatures.sql
--
-- ALL EIGHT ARE NEW: catalog-diff --remote matched none on the survey date and
-- none of the slugs exists in production (checked again immediately before
-- this file).
--
-- EXTRACTED by book-extract-worker, every number read off a 200 dpi render
-- rather than the OCR cache. RECONCILED by book-reconcile against the pages,
-- row by row: every number agreed, and it found the NPCs' natural_abilities
-- dropping their printed regeneration rates, night-vision ranges and teleport
-- percentages; those figures were added. Both creature rows pass
-- creatureFormulaGaps, the grammar the endpoint rolls with.
--
-- A title is not the name (Yahuar Huacac, title the Blood Weeper), as in #1164.
-- The Heroes of the Sun (47-48) is a list with no stat blocks, and Overlord
-- Enno (70) and the Dakir (100) are prose; none is a row.
--
-- description, disposition and natural_abilities are short paraphrases - no
-- sentence is the book's.

INSERT OR IGNORE INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'viracocha', 'Viracocha', NULL, 'the All-Father', 'rifts', NULL, 'Ley Line Walker and Shifter (equivalent)', 20, 'Principled', NULL, NULL, NULL, '{"IQ":28,"ME":30,"MA":22,"PS":45,"PP":26,"PE":25,"PB":20,"Spd":40}', NULL, NULL, 15000, 10000, 1000, NULL, 15, '{"attacks":7,"initiative":5,"strike":8,"parry":11,"dodge":11,"roll":6,"pull":6}', '+6 save vs magic, +10 save vs horror factor. M.D.C. rises to 75,000 in the city of Cuzco, and was 150,000 at the height of his power. P.B. 20 and Spd 40 do not apply in energy form; Spd is 200 in energy form.', '[{"name":"Demon and Monster Lore","pct":98},{"name":"Faerie Lore","pct":98},{"name":"Detect Ambush and Concealment","pct":98}]', 'Magically knows all languages; literate in Dragonese/Elven, Spanish, Quechua and American. W.P. sword, W.P. shield, W.P. archery and targeting. Combat equal to hand to hand: martial arts plus special bonuses.', 'Sees invisible things and in total darkness, regenerates fast, resists heat, cold and mind control, heals with a touch, and can banish minor spirits and demons. Bio-regenerates 1D4x100 M.D.C. per minute; half damage from mega-damage energy attacks.', 'Knows all spells levels 1-15, equal to a 20th level ley line walker. Can close or open Rifts without the normal cost, start or stop ley line storms, and fire dimensional energy bolts that trigger a d100 side-effect table (aging, teleport, dimensional shift, etc.).', 'All healing and sensitive powers plus empathic transmission, group mind block and mind block auto-defense; equal to a 15th level psychic.', NULL, NULL, 'Two energy swords that appear at will (1D6x10+10 M.D. plus normal hand to hand damage). Enchanted, highly stylized plate body armor, 2,000 M.D.C.', 'Access to literally billions of credits worth of cash, weapons and vehicles as titular head of the Inca Empire.', 'Reserved and perceptive, friendly but distant; patient with the troubled but angered by evil and anarchist alignments, with honorable exceptions; avoids unprovoked violence except against inherently evil beings.', 'Other gods of the Pantheon of the Sun; also the gods Zurvan, Ra and Brahma, and other gods of light.', 'Takes triple damage from evil-aligned rune swords.', 'Ancient dimensional-energy being who survived a Megaverse-spanning war called the Shattering; now takes a near-Andean human form and leads the Pantheon of the Sun, focused on dimensional magic and defending against the Splugorth, vampires and the Arkhon.', 'Rifts World Book 9: South America 2 p.41-42');
INSERT OR IGNORE INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'inti', 'Inti', NULL, 'the Sun God', 'rifts', NULL, 'Ley Line Walker and Psychic (equivalent)', 15, 'Scrupulous with unprincipled or anarchist leanings', NULL, NULL, NULL, '{"IQ":22,"ME":26,"MA":21,"PS":35,"PP":24,"PE":27,"PB":19,"Spd":60}', NULL, NULL, 10000, 5000, 700, NULL, 14, '{"attacks":6,"initiative":3,"strike":7,"parry":10,"dodge":10,"roll":4,"pull":6}', 'M.D.C. rises to 50,000 in Cuzco, and was 100,000 at the peak of his power. P.B. 19 and Spd 60 do not apply in energy form; Spd is 200 in energy form.', '[{"name":"Demon and Monster Lore","pct":98},{"name":"Faerie Lore","pct":98},{"name":"Detect Ambush and Concealment","pct":98},{"name":"Holistic Medicine","pct":98}]', 'Magically knows all languages; literate in Dragonese/Elven, Spanish, Quechua and American. Combat equal to hand to hand: martial arts with special bonuses.', 'Sees invisible things and in total darkness, regenerates fast, resists heat and cold, heals with a touch, and can teleport between dimensions he has visited. Bio-regenerates 1D4x100 M.D.C. per minute; half damage from mega-damage energy attacks; dimensional teleport 88%.', 'Knows all spells levels 1-15, equal to a 15th level wizard.', 'All sensitive and physical powers, equal to a 15th level mind melter.', NULL, NULL, 'None. Relies exclusively on his own powers, including radiant blinding light, energy blasts and force fields (up to 500 M.D.C., costing 100 P.P.E. to raise).', 'Access to billions of credits in cash and equipment.', 'Quicker to anger than his brother, provoked by cruelty and injustice; growing tempted by a hunger for power that worries his allies.', 'Gods of light; secretly in contact with the ancient temporal raider Eingred, who is unknowingly (to Inti) working with a goqua trying to corrupt him.', 'Takes triple damage from evil-aligned rune weapons; deep enmity with vampires and the mysterious Nightlords.', 'Energy being who appears as blinding light or a glowing human form, identified with the sun; pushing to expand the Empire of the Sun and growing more hostile toward the Arkhons.', 'Rifts World Book 9: South America 2 p.42-43');
INSERT OR IGNORE INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'pachamama', 'Pachamama', NULL, 'the All Mother', 'rifts', NULL, 'Warlock and Mind Melter (equivalent)', 20, 'Principled', NULL, NULL, NULL, '{"IQ":30,"ME":28,"MA":32,"PS":28,"PP":20,"PE":30,"PB":24,"Spd":70}', NULL, NULL, 12000, 9000, 2000, NULL, 12, '{"attacks":5,"initiative":1,"strike":5,"parry":6,"dodge":6,"roll":4,"pull":4}', 'M.D.C. rises to 60,000 in Cuzco. +4 save vs magic, +10 save vs horror factor.', '[{"name":"Demon and Monster Lore","pct":98},{"name":"Faerie Lore","pct":98},{"name":"Holistic Medicine","pct":98}]', 'Magically knows all languages; literate in Dragonese/Elven, Spanish, Quechua and American. Combat equal to hand to hand: basic.', 'Regenerates fast, sees invisible things, takes half damage from ordinary attacks; senses life, quakes, weather and ley lines anywhere she touches open earth, blocked by pavement or buildings; can speed crop growth and yield, heal up to 100 points per round, and sometimes raise the dead. Bio-regenerates 2D6x10 M.D.C. per melee round.', 'Knows all earth warlock spells, equal to a 20th level warlock.', 'All sensitive, healing and physical powers at 20th level, plus a psi-sword.', NULL, NULL, 'None beyond her psi-sword; relies on her powers.', 'Access to billions of credits.', 'Distracted, as if always listening to the pulse of life; compassionate even to her lowest servants, unmoved by necessary killing but reviling needless cruelty.', 'Respected by beings of the elemental plane of earth; can summon 2D6 minor earth elementals routinely, or up to 5,000 minor and 500 greater elementals in an emergency.', 'Despises the undead, especially the Blood Weeper, whose hidden city she has not yet found.', 'Formerly the living consciousness of the destroyed elemental world Paxull, rescued by Viracocha and Inti and now his consort; can take any human female form and stays bonded to the life of every world she touches.', 'Rifts World Book 9: South America 2 p.44-45');
INSERT OR IGNORE INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'illapa', 'Illapa', NULL, 'God of Thunder and Storm', 'rifts', NULL, 'Air and Water Warlock (equivalent)', 20, 'Principled', NULL, NULL, NULL, '{"IQ":22,"ME":18,"MA":22,"PS":40,"PP":26,"PE":23,"PB":4,"Spd":60}', NULL, 4000, 9000, 6000, 700, NULL, 13, '{"attacks":8,"initiative":3,"strike":10,"parry":12,"dodge":12,"roll":6,"pull":8}', 'M.D.C. rises to 45,000 in the Cuzco area. Astral form has 4,000 S.D.C. and no connecting silver cord. +5 save vs magic, +8 save vs horror factor. Can fly at up to Mach 10.', '[{"name":"Demon and Monster Lore","pct":98},{"name":"Faerie Lore","pct":98},{"name":"Wilderness Survival","pct":98}]', 'Knows all languages magically; literate in over 20, including Quechua, Spanish, Aymara and American. W.P. archery and targeting, W.P. blunt. Combat equal to hand to hand: martial arts with extra bonuses.', 'Turns invisible at will, sees invisible things, regenerates fast, immune to electrical damage and resistant to other energy attacks; teleports without error and between dimensions he has visited; can start or stop rain and reshape weather over a wide area, can compel air and water elementals to obey, and can project himself into astral form to visit people''s dreams. Bio-regenerates 3D6x10 M.D.C. per minute; teleports without error up to 100 miles (160 km); dimensional teleport 88%.', 'Knows all air and water warlock spells levels 1-8 at 20th level proficiency.', 'All sensitive powers, equal to a 10th level psychic, plus his own astral abilities.', NULL, NULL, 'The Mace of the Elements (indestructible, extra damage to creatures vulnerable to Millennium Trees, can cast rain dance, summon storm and drought three times each per day at 10th level, and heal up to six times a day). The Golden Sling (fires lightning bolts). Typically no body armor.', 'Access to the Imperial treasury: billions of credits, vehicles and equipment.', 'Protective of his worshippers and quick to anger at those who abuse weather magic to dominate others; pushing for war against the Aztec gods while Viracocha counsels patience.', 'Connections to the elemental planes of air and water; some elemental intelligences respect him, others resent his influence.', 'The Aztec god Tlaloc, whom Illapa wants his pantheon to go to war against.', 'Warrior and fertility god of thunder and storms, allied to the Pantheon of the Sun after Viracocha helped free his world from demons; visits priests through dreams during storms.', 'Rifts World Book 9: South America 2 p.45-46');
INSERT OR IGNORE INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'manco-capac', 'Manco Capac', NULL, 'The First Inca', 'rifts', 'True Inca', 'Godling', 14, 'Scrupulous', NULL, NULL, NULL, '{"IQ":17,"ME":20,"MA":18,"PS":32,"PP":22,"PE":25,"PB":22,"Spd":30}', NULL, NULL, 601, 305, 132, NULL, 10, '{"attacks":7,"initiative":4,"strike":7,"parry":10,"dodge":10,"roll":5,"pull":6}', 'Horror Factor is 10 if his true nature (as a godling) is revealed, 11 if his true identity (as Manco Capac) is revealed. +2 save vs magic, +8 save vs horror factor. Seven hand to hand attacks per melee, or two by magic.', '[{"name":"Dragonese/Elven","pct":98},{"name":"Quechua","pct":98},{"name":"Spanish","pct":98},{"name":"American","pct":98},{"name":"Demon and Monster Lore","pct":98},{"name":"Wilderness Survival","pct":98}]', 'W.P. energy rifle, energy pistol, sword, archery and targeting, blunt and heavy energy weapons. Combat equal to hand to hand: martial arts plus boxing and special bonuses.', 'Sees invisible things, regenerates fast, has nightvision, can exorcise spirits, and resists possession and mind control. Regenerates 1D4x10 M.D.C. per minute (4 melee rounds); nightvision 200 feet (61 m); exorcises spirits at 60% +3% per additional level.', 'Knows all spells levels 1-3 plus carpet of adhesion, heal wounds, call lightning, fire ball, fly as the eagle and mystic portal.', 'All sensitive and healing powers.', NULL, NULL, 'The Sword of Manco Inca, a captured and enchanted Spanish greatsword (heals, senses evil, casts Armor of Ithan, and does double damage to vampires and alien intelligences). Gilded body armor, 70 M.D.C.', '4D6 million credits on short notice, ten times as much within a day or so.', 'Humble and warm toward ordinary people despite his heroic status, quick with a comforting smile, but merciless toward vampires, demons and devils.', 'Leads the Heroes of the Sun (Manco Capac''s Chosen), roughly 200 champions including dragons, cosmo-knights, other True Incas, Anti-Monsters, True Atlanteans and more.', 'The Aztec god Tlaloc, whom he barely survived fighting.', 'Foremost of the True Incas and Viracocha''s herald and scout for over 20,000 years; prefers frontline combat and disguise to ruling, and is now exploring Rifts Earth beyond South America for the gods.', 'Rifts World Book 9: South America 2 p.46-47');
INSERT OR IGNORE INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES (
  'yahuar-huacac', 'Yahuar Huacac', NULL, 'the Blood Weeper', 'rifts', 'Ancient (Incan Undead)', 'Necromancer', 12, 'Diabolic and maniacal', NULL, NULL, NULL, '{"IQ":25,"ME":19,"MA":13,"PS":40,"PP":23,"PE":18,"PB":3,"Spd":22}', NULL, NULL, 6000, 1500, 241, NULL, 16, '{"attacks":7,"initiative":1,"strike":9,"parry":9,"dodge":9,"roll":4,"pull":4}', 'M.D.C. enhanced through the power of the forces of darkness. +3 save vs magic, +10 save vs horror factor. Seven attacks per melee, or two by magic. Horror Factor rises to 18 while weeping blood.', '[{"name":"Spanish","pct":98},{"name":"Quechua","pct":98},{"name":"Aymara","pct":98},{"name":"Creole","pct":98},{"name":"American","pct":98},{"name":"Demon and Monster Lore","pct":98},{"name":"Vampire and Undead Lore","pct":98}]', 'W.P. sword. Combat equal to hand to hand: assassin.', 'Undead; sees in total darkness, regenerates fast but is badly hurt by fire; withering touch drains and weakens a victim; commands far more undead than an ordinary Ancient and can attempt to dominate vampires; immune to other undead''s mind control, possession and the vampire''s slow-kill bite; when strongly moved he weeps blood he can fling as a burning, fear-inducing attack. Regenerates 2D6x10 M.D.C. every minute (4 melee rounds); nightvision 2000 feet (610 m).', 'Knows all spells levels 1-10 plus all necromantic powers, including wearing animated supernatural remains as armor.', 'All sensitive powers plus empathic transmission, hypnotic suggestion, mentally possess others, psi-shield, and a psi-sword.', NULL, NULL, 'Enchanted poncho and face mask, 120 M.D.C., blocks flame attacks until destroyed; otherwise relies on his powers and psi-sword.', 'Over 10 billion credits in gold, jewels and treasure, buried beneath the City of the Dead and guarded by demons.', 'Any humanity burned away by centuries of undeath; obsessed with dominating both the living and the dead, dreaming of a coast-to-coast realm of the walking dead.', 'Sinchi Yahuar (a goqua advisor), a vampire intelligence, and various necromancers, demons and vampires; commands dozens of lesser Ancients, zombies, mummies, skeletons, ghouls and other undead.', 'Manco Capac and the Heroes of the Sun, whom he blames for destroying his demon and vampire bodyguards; hates his former gods.', 'The seventh Inca Emperor, turned toward necromancy after an early kidnapping and mentorship by an evil sorcerer; weeps tears of blood when moved to strong emotion; now the most powerful of the Ancients, ruling the City of the Dead.', 'Rifts World Book 9: South America 2 p.50-52');

INSERT OR IGNORE INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'ancient', 'Ancient', 'undead', 'rifts', 0, 'Any evil, but usually miscreant or diabolic', '{"IQ":"3D6+8","ME":"3D6+6","MA":"3D6","PS":"4D6+24","PP":"3D6+8","PE":"3D6+4","PB":"1D6","Spd":"4D6+6"}', NULL, NULL, '1D4X1000', '2D6X100', '3D6X10+ME', 'P.P.E. gains +50 per additional level of experience; I.S.P. gains +12 per additional level of experience. Experience level averages 1D4+5.', NULL, 14, '{"attacks":"varies by skill, plus one additional melee attack","initiative":null,"strike":1,"parry":1,"dodge":2}', '+3 to save vs magic, +9 to save vs horror factor, plus attribute and skill bonuses.', 'Quechua and five other languages at 98%; seven Technical skills at +20%; ten additional skills at +5%, typically weapon proficiencies, hand to hand (basic counts as one selection, expert as two, martial arts or assassin as three), and wilderness or domestic skills; rarely interested in technological skills.', 'Undead body that never ages and needs no rest; sees in total darkness; regenerates fast but takes double damage from mega-damage fire and triple from magic or psionic fire (only half damage from other non-magical attacks); withering touch drains a victim''s life force and can trigger a fatal coma; commands lesser undead and can attempt to dominate vampires; immune to mind control, possession by other undead, and a vampire''s slow-kill bite; must feed with its withering touch about once a month or begin wasting away. Regenerates 2D6x10 M.D.C. every minute (4 melee rounds); nightvision 2000 feet (610 m).', 'Knows all spells levels 1-5, plus three spells from each level up to its own experience level, and one spell from every level above that, drawn from the common or necromantic spell list; about half are necromancers. Spell strength scales like a ley line walker.', 'All sensitive powers plus psi-sword and four super psionic powers of choice; master psionic.', 'Average height five feet, five inches (1.65 m)', NULL, 'Undead - does not age or die naturally, but can be destroyed', 'Remote mountain fortresses (such as the City of the Dead) and hidden sites throughout the Andes and surrounding jungles', 'Other Ancients, and sometimes other undead (including vampires), demons, necromancers and other powerful evil beings', 'The gods of the Pantheon of the Sun, who hunt and destroy Ancients on sight', 'Vulnerable to fire: even S.D.C. fire does M.D. damage (1D6 M.D. from a torch, 6D6 M.D. from a bonfire); mega-damage fire does double damage and magic or psionic fire does triple. Weapons: mostly enchanted clubs (3D6 M.D. plus supernatural strength damage); a few carry captured energy or T.W. weapons and covet rune weapons but rarely have them. Body armor: enchanted poncho and face mask, 120 M.D.C., protects from flame attacks until destroyed. Money: hoards of plunder worth roughly 1D6 million credits; little other equipment.', 'Mummified pre-Rifts Inca nobles and rulers whose preservation rituals trapped their life-force in undeath; centuries of imprisonment and isolation drove most insane and hateful of the living; not suitable as player characters.', 'Rifts World Book 9: South America 2 p.48-50');
INSERT OR IGNORE INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES (
  'war-bison', 'War Bison', 'animal', 'rifts', 0, 'Considered to be diabolic or aberrant', '{"IQ":"2D4+3","ME":"2D6","MA":"2D4","PS":"2D6+30","PP":"1D6+18","PE":"2D6+14","PB":"1D4","Spd":"2D4X10+80"}', NULL, NULL, '1D4X100+100', '3D6+8', NULL, 'No hit points or S.D.C.; the creature is entirely mega-damage.', NULL, 9, '{"attacks":4,"initiative":1,"strike":2,"parry":1,"dodge":1}', '+4 to save vs magic and disease, in addition to attribute bonuses. Horror Factor rises to 13 if the Larhold are known to be a menace.', 'Understands (but cannot speak) Larhold, 65%.', 'Nightvision 600 ft (183 m); regenerates 1D4x10 M.D. per minute.', NULL, NULL, '5-7 ft (1.5 to 2.1 m) at the shoulder, head adds another 1-3 ft; 7 to 10 ft (2.1 to 3.0 m) long', '1,000 to 4,000 lbs (450 to 1,800 kg)', '70 years', 'Typically plains and woodlands', 'Bonded to the Larhold who ride and keep them', 'All enemies of the Larhold', 'Serves as the Larhold''s mount and their measure of wealth; a war bison is worth roughly 50,000 to 100,000 credits (comparable to a tank), though they are not for sale.', 'Predatory relative of the bison, with four horns and unnervingly intelligent, malevolent eyes; hunts live prey despite its herbivore-like build, possibly the product of magic or gene-splicing.', 'Rifts World Book 9: South America 2 p.187-188');

INSERT OR IGNORE INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
  ('notable_npc', 'viracocha', 'Energy sword', '1D6x10+10 M.D. plus hand to hand damage', 1, 'melee', 'wields two at once', 1),
  ('notable_npc', 'viracocha', 'Dimensional blast', '1D4x10 M.D. to supernatural beings/mega-damage materials, or 5D6 S.D.C. to others', 1, 'line of sight', '+4 to strike; those hit roll on a d100 side-effect table', 2),
  ('notable_npc', 'inti', 'Energy blast', 'up to 4D6x10 M.D., adjustable in 1D6 M.D. increments', 1, '2000 ft (610 m)', '+3 to strike', 1),
  ('notable_npc', 'pachamama', 'Psi-sword', '14D6 M.D. or 2D4x10 M.D.', 1, 'melee', 'psionic power', 1),
  ('notable_npc', 'illapa', 'Mace of the Elements', '3D4x10 M.D.', 1, 'melee', 'indestructible; extra damage to creatures vulnerable to Millennium Trees', 1),
  ('notable_npc', 'illapa', 'Golden Sling of Thunder', '2D6x10 M.D.', 1, '4000 ft (1220 m)', 'fires lightning bolts', 2),
  ('notable_npc', 'manco-capac', 'Sword of Manco Inca', '6D6+6 M.D.', 1, 'melee', 'holy weapon; double damage to vampires and alien intelligences', 1),
  ('notable_npc', 'yahuar-huacac', 'Blood fling', '4D6 M.D.', 1, '10 ft (3 m)', 'additional attack while weeping blood; victim saves vs magic or is gripped by fear at horror factor 18', 1),
  ('notable_npc', 'yahuar-huacac', 'Withering touch', '2D6 damage on a successful save, or 1D4x10 damage plus weakening on a failed save', 1, 'melee (hand to hand attack)', 'does no other damage; same as the Ancient R.C.C.; victim saves vs magic at 14 or higher', 2),
  ('notable_npc', 'yahuar-huacac', 'Psi-sword', '12D6 M.D.', 1, 'melee', 'psionic weapon', 3),
  ('creature', 'ancient', 'Withering touch', '2D6 M.D. or hit points on a successful save, or 1D4x10 M.D. or hit points plus weakening on a failed save', 1, 'melee (hand to hand attack)', 'does no other damage; victim saves vs magic at 14 or higher', 1),
  ('creature', 'ancient', 'Enchanted club', '3D6 M.D. plus supernatural P.S. damage', 1, 'melee', 'most Ancients'' usual weapon', 2),
  ('creature', 'war-bison', 'Bite', '4D6 M.D.', 1, 'melee', NULL, 1),
  ('creature', 'war-bison', 'Head Butt', '5D6 M.D. if standing still, or 1D4x10 M.D. with a running start', 1, 'melee', NULL, 2),
  ('creature', 'war-bison', 'Power Butt', '1D6x10+10 M.D.', 1, 'melee', 'counts as two melee attacks', 3);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'the 6 notable NPCs are in' AS assertion, count(*) AS got, 6 AS want
  FROM notable_npcs WHERE slug IN ('viracocha', 'inti', 'pachamama', 'illapa', 'manco-capac', 'yahuar-huacac');
SELECT 'the 2 creatures are in' AS assertion, count(*) AS got, 2 AS want
  FROM creatures WHERE slug IN ('ancient', 'war-bison');
SELECT 'their 15 attacks are in' AS assertion, count(*) AS got, 15 AS want
  FROM stat_attacks WHERE (owner_kind = 'notable_npc' AND owner_slug IN ('viracocha', 'inti', 'pachamama', 'illapa', 'manco-capac', 'yahuar-huacac')) OR (owner_kind = 'creature' AND owner_slug IN ('ancient', 'war-bison'));

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('add-south-america-2-npcs-and-creatures.sql');
